.btn-secondary {
    background: #607D8B;
    color: white;
}

.table-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 15px;
    padding: 20px;
}

.table-card {
    background: rgba(255,255,255,0.1);
    border-radius: 10px;
    padding: 15px;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
    border: 2px solid transparent;
}

.table-card:hover {
    background: rgba(255,255,255,0.2);
    transform: translateY(-2px);
}

.table-card.empty {
    border-color: #4CAF50;
}

.table-card.waiting {
    border-color: #FFC107;
}

.table-card.playing {
    border-color: #2196F3;
}

.table-card.full {
    border-color: #f44336;
    opacity: 0.7;
}

.table-card.new-table {
    background: rgba(76, 175, 80, 0.3);
    border: 2px dashed #4CAF50;
}

.table-number {
    font-size: 1.5em;
    font-weight: bold;
    margin-bottom: 10px;
}

.table-status {
    font-size: 0.9em;
    color: #ccc;
}

.table-players {
    margin-top: 10px;
    font-size: 0.8em;
}

/* 牌桌列表中的小型圆桌布局 */
.mini-table-layout {
    position: relative;
    width: 120px;
    height: 120px;
    margin: 10px auto;
}

.mini-table-center {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, #2d5a3d 0%, #1a3d2a 100%);
    border: 2px solid #FFD700;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
}

.mini-seat {
    position: absolute;
    text-align: center;
    width: 32px;
}

/* 逆时针顺序: 1(底) → 2(右) → 3(顶) → 4(左) */
.mini-seat-1 { bottom: 0; left: 50%; transform: translateX(-50%); }
.mini-seat-2 { right: 0; top: 50%; transform: translateY(-50%); }
.mini-seat-3 { top: 0; left: 50%; transform: translateX(-50%); }
.mini-seat-4 { left: 0; top: 50%; transform: translateY(-50%); }

.mini-seat-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: bold;
    border: 2px solid #555;
    transition: all 0.3s;
    color: #fff;
}

.mini-seat-avatar.occupied {
    background: linear-gradient(135deg, #4CAF50, #2E7D32);
    border-color: #81C784;
}

