// 确保已登录
function ensureLogin(callback) {
    const name = document.getElementById('playerName').value.trim();
    if (!name) {
        alert('请先输入名称');
        return false;
    }

    if (!playerId || !playerName) {
        playerName = name;
        if (!ws || ws.readyState !== WebSocket.OPEN) {
            connect();
            setTimeout(() => {
                ws.send(JSON.stringify({ type: 'login', name }));
                if (callback) setTimeout(callback, 300);
            }, 500);
        } else {
            ws.send(JSON.stringify({ type: 'login', name }));
            if (callback) setTimeout(callback, 300);
        }
        return true;
    }
    return true;
}

// 登录
function login() {
    const name = document.getElementById('playerName').value.trim();
    if (!name) {
        alert('请输入名字');
        return;
    }

    playerName = name;
    if (!ws || ws.readyState !== WebSocket.OPEN) {
        connect();
        setTimeout(() => {
            ws.send(JSON.stringify({ type: 'login', name }));
        }, 500);
    } else {
        ws.send(JSON.stringify({ type: 'login', name }));
    }
}

// 退出
